result:
.content {
  min-height: 600px;
  padding-right: 400px;

  .left {
    display: flex;
    justify-content: center;

    .phone {
      position: relative;
      margin-top: 61px;
      width: 375px;
      height: 667px;
      overflow: hidden;

      img {
        width: 100%;
        height: 100%;
      }

      .mask {
        position: absolute;
        top: 0;
        right: 0;
        bottom: 0;
        left: 0;
        height: auto;
        background: #333333;
        opacity: 0.5;
        z-index: 9;
      }
    }
  }

  .right {
    width: 400px;
    position: fixed;
    top: 78px;
    right: 14px;
    bottom: 78px;
    overflow-y: auto;
    background-color: #fff;

    /deep/ .main-content {
      border-top: 6px solid #f0f2f5;
    }
  }
}

.main {
  .main-header {
    padding: 20px 15px;
    background: #ffffff;
    font-weight: 500;
    font-size: 16px;
    line-height: 16px;
    color: #333333;
  }

  .main-content {
    border-top: 6px solid #f0f2f5;
    padding: 20px 15px;
    background: #ffffff;

    .title {
      font-size: 14px;
      line-height: 14px;
      color: #333333;
    }

    .form {
      .tip {
        padding: 28px 0 20px;
        font-size: 12px;
        line-height: 12px;
        color: #bbbbbb;
      }

      .form-item:last-child {
        margin-bottom: 0;
      }

      .form-item {
        font-size: 12px;
        line-height: 12px;

        .form-label {
          width: 95px;
          color: #999999;
        }

        .form-value {
          flex: 1;
          color: #666666;

          /deep/ .ivu-radio-group {
            margin: 0 -8px -20px 0;
          }

          /deep/ .ivu-radio-wrapper {
            width: 83px;
            margin-bottom: 20px;
          }

          /deep/ .ivu-radio {
            margin-right: 10px;
          }

          .picTxt {
            display: flex;
            align-items: center;

            .tip {
              margin-left: 16px;
              font-size: 12px;
              color: #bbbbbb;
            }
          }

          .pictrue {
            width: 64px;
            height: 64px;
          }

          .upload-box {
            display: flex;
            align-items: center;
            justify-content: center;
            width: 64px;
            height: 64px;
            border: 1px solid #eeeeee;
            border-radius: 4px;

            .ivu-icon {
              color: #bbbbbb;
            }
          }
        }
      }
    }
  }
}

.fab-wrapper {
  position: absolute;
  right: 10px;
  z-index: 10;
  padding: 5px;
  border-radius: 23px;
  background: rgba(255, 255, 255, 0.5);

  .btn {
    width: 35px;
    height: 35px;
    border-radius: 50%;
    background: #ffffff;
    & + .btn {
      margin-top: 8px;
    }

    img {
      display: block;
      width: 100%;
      height: 100%;
      border-radius: 50%;
    }
  }

  &.style2 {
    right: 0;
    display: flex;
    align-items: center;
    border-radius: 37px 0px 0px 37px;

    .btn {
      margin: 0 8px 0 0;
    }
    .iconfont {
      width: 14px;
      height: 14px;
      margin: 0 5px 0 0;
      font-size: 14px;
      line-height: 14px;
      text-align: center;
    }
  }
}

.box-item {
  position: relative;
  display: flex;
  padding: 14px 20px 16px 0;
  border-radius: 3px;
  margin-bottom: 20px;
  background: #f9f9f9;

  .del-box {
    position: absolute;
    right: 0;
    top: 0;
    cursor: pointer;
    transform: translate(50%, -50%);

    .iconfont {
      font-size: 16px;
      color: #cccccc;
    }
  }
}

.left-tool {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 40px;

  .iconfont {
    color: #dddddd;
    font-size: 18px;
    cursor: move;
  }
}

.right-wrapper {
  flex: 1;

  .cell + .cell {
    margin-top: 13px;
  }

  .item-title {
    color: #999999;
    font-size: 12px;
    width: 40px;
  }

  .img-wrapper {
    display: flex;

    .img-item {
      width: 64px;
      height: 64px;
      margin-right: 20px;

      .name {
        color: #bbbbbb;
        font-size: 12px;
        text-align: center;
        margin-top: 7px;
      }

      .pictrue {
        width: 100%;
        height: 100%;
        cursor: pointer;
        border: 1px solid #eeeeee;
        position: relative;
        border-radius: 3px;
      }

      img {
        display: block;
        width: 100%;
        height: 100%;
      }

      .empty-img {
        display: flex;
        align-items: center;
        justify-content: center;
        flex-direction: column;
        width: 100%;
        height: 100%;
        font-size: 12px;
        color: #bfbfbf;
        border: 1px solid #eeeeee;
        border-radius: 3px;

        .iconfont {
          font-size: 24px;
        }
      }

      .txt {
        position: absolute;
        left: 0;
        bottom: 0;
        width: 100%;
        height: 22px;
        line-height: 22px;
        text-align: center;
        background: rgba(0, 0, 0, 0.5);
        color: #fff;
        font-size: 12px;
        border-radius: 0 0 3px 3px;
      }
    }
  }

  .slider-box {
    flex: 1;
  }
}

.add-btn {
  width: 100%;
  height: 36px;
  border-radius: 3px;
  border-color: #eeeeee;
  color: #666666;
}

.fixed-card {
  position: fixed;
  right: 0;
  bottom: 0;
  left: 200px;
  z-index: 99;
  box-shadow: 0 -1px 2px rgb(240, 240, 240);
  padding-right: 400px;
}
.style3 {
