      top: -27px;
      right: 51px;
    }
    &:nth-child(3) {
      top: 27px;
      right: 51px;
    }
    &:nth-child(4) {
      top: 56px;
      right: 6px;
    }
  }
  .btn5 {
    position: absolute;
    width: 35px;
    height: 35px;
    border-radius: 50%;
    margin: 0;
    background: #ffffff;
    box-shadow: 0px 0px 8px 0px rgba(0, 0, 0, 0.1);
    &:nth-child(1) {
      top: -57px;
      right: 0;
    }
    &:nth-child(2) {
      top: -42px;
      right: 44px;
    }
    &:nth-child(3) {
      top: 0;
      right: 57px;
    }
    &:nth-child(4) {
      top: 42px;
      right: 44px;
    }
    &:nth-child(5) {
      top: 57px;
      right: 0;
    }
  }
}
.style4 {
  right: -62px;
  width: 175px;
  height: 175px;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.5);
  box-shadow: 0px 0px 7px 0px rgba(0, 0, 0, 0.1);
  .inner {
    position: absolute;
    top: 50%;
    right: 70px;
    transform: translateY(-50%);
  }
  .main-btn {
    width: 35px;
    height: 35px;
    border-radius: 50%;
    background: #ffffff;
    box-shadow: 0px 0px 8px 0px rgba(0, 0, 0, 0.1);
  }
  .btn {
    position: absolute;
    width: 35px;
    height: 35px;
    background: #ffffff;
    box-shadow: 0px 0px 8px 0px rgba(0, 0, 0, 0.1);
    +.btn{
      margin: 0;
    }
    &:nth-child(1) {
      top: -57px;
      right: 0;
    }
    &:nth-child(2) {
      top: -42px;
      right: 44px;
    }
    &:nth-child(3) {
      top: 0;
      right: 57px;
    }
    &:nth-child(4) {
      top: 42px;
      right: 44px;
    }
    &:nth-child(5) {
      top: 57px;
      right: 0;
    }
  }
}
